    for dx, dy in deltas:
        nx, ny = sx + dx, sy + dy
        if not inb(nx, ny) or (nx, ny) in obstacles:
            continue

        # Evaluate best immediate resource advantage from the prospective position.
        local_best_adv = -10**9
        local_best_dist = 10**9
        for rx, ry in resources:
